// Tests for CerebralComponent class
import { Component, ChangeDetectionStrategy, Input } from '@angular/core'
import { state, View } from 'cerebral'
import { CerebralComponent } from '../src/CerebralComponent'
import { createMockCdr } from './helpers'
import { CerebralTest } from 'cerebral/test'

describe('CerebralComponent basics', () => {
  it('should require ChangeDetectorRef and AppService', () => {
    expect(() => new CerebralComponent(null, {})).toThrow(/ChangeDetectorRef/)

    const cdr = createMockCdr()
    expect(() => new CerebralComponent(cdr, null)).toThrow(/AppService/)

    const app = { flush: jest.fn() }
    const component = new CerebralComponent(cdr, app)
    expect(component._cdr).toBe(cdr)
    expect(component._app).toBe(app)
  })

  it('should provide base lifecycle methods', () => {
    const cdr = createMockCdr()
    const app = { flush: jest.fn() }
    const component = new CerebralComponent(cdr, app)

    expect(typeof component.ngOnInit).toBe('function')
    expect(typeof component.ngOnDestroy).toBe('function')
    expect(typeof component.ngAfterViewInit).toBe('function')
    expect(typeof component.ngOnChanges).toBe('function')
  })
})

@Component({
  template: '<div>{{count}}</div>',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
class TestComponent extends CerebralComponent {
  count: number = 0
  ngOnInitCalled = false
  ngAfterViewInitCalled = false
  ngOnDestroyCalled = false
  ngOnChangesCalled = false

  ngOnInit(): void {
    super.ngOnInit()
    this.ngOnInitCalled = true
  }

  ngAfterViewInit(): void {
    super.ngAfterViewInit()
    this.ngAfterViewInitCalled = true
  }

  ngOnDestroy(): void {
    super.ngOnDestroy()
    this.ngOnDestroyCalled = true
  }

  ngOnChanges(): void {
    super.ngOnChanges()
    this.ngOnChangesCalled = true
  }
}

@Component({
  template: '<div>{{count}}</div>',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
class InputComponent extends CerebralComponent {
  @Input() propA: string = ''
  @Input() propB: number = 0
  count: number = 0
}

describe('CerebralComponent lifecycle methods', () => {
  it('should call all lifecycle hooks correctly', () => {
    const test = CerebralTest({ state: { count: 0 } })
    const cdr = createMockCdr()
    const component = new TestComponent(cdr, test.controller)

    const ngOnInitSpy = jest.spyOn(component, 'ngOnInit')
    const ngAfterViewInitSpy = jest.spyOn(component, 'ngAfterViewInit')
    const ngOnChangesSpy = jest.spyOn(component, 'ngOnChanges')
    const ngOnDestroySpy = jest.spyOn(component, 'ngOnDestroy')

    component.ngOnInit()
    component.ngAfterViewInit()
    component.ngOnChanges()
    component.ngOnDestroy()

    expect(ngOnInitSpy).toHaveBeenCalled()
    expect(ngAfterViewInitSpy).toHaveBeenCalled()
    expect(ngOnChangesSpy).toHaveBeenCalled()
    expect(ngOnDestroySpy).toHaveBeenCalled()

    expect(component.ngOnInitCalled).toBeTruthy()
    expect(component.ngAfterViewInitCalled).toBeTruthy()
    expect(component.ngOnChangesCalled).toBeTruthy()
    expect(component.ngOnDestroyCalled).toBeTruthy()
  })

  it('should handle view operations correctly on state changes', () => {
    const test = CerebralTest({ state: { count: 0 } })
    const cdr = createMockCdr()
    const component = new TestComponent(cdr, test.controller)

    component.onUpdate = (changes: any, force: any) => {
      if (component.view) {
        component.view.updateFromState(changes, {}, force)
        component.view.render(
          {},
          (props: any) => {
            Object.assign(component, props)
          },
          false
        )
      }
      component._cdr.detectChanges()
    }

    component.view = new View({
      dependencies: { count: state`count` },
      props: {},
      controller: test.controller,
      displayName: 'TestComponent',
      onUpdate: component.onUpdate,
    })
    component.view.mount()
    component.view.render(
      {},
      (props: any) => Object.assign(component, props),
      true
    )

    test.setState('count', 42)
    component.onUpdate({}, true)

    expect(component.count).toBe(42)
    expect(cdr.detectChanges).toHaveBeenCalled()
  })

  it('should handle ngOnInit when view is already defined', () => {
    const test = CerebralTest({ state: { count: 0 } })
    const cdr = createMockCdr()
    const component = new TestComponent(cdr, test.controller)

    component.onUpdate = jest.fn()
    component.view = new View({
      dependencies: { count: state`count` },
      props: {},
      controller: test.controller,
      displayName: 'TestComponent',
      onUpdate: component.onUpdate,
    })

    const originalView = component.view
    component.ngOnInit()

    expect(component.ngOnInitCalled).toBeTruthy()
    expect(component.view).toBe(originalView)
  })
})

describe('CerebralComponent with props', () => {
  it('should handle prop changes', () => {
    const test = CerebralTest({ state: { count: 0 } })
    const cdr = createMockCdr()
    const component = new InputComponent(cdr, test.controller)

    component.onUpdate = jest.fn()
    component.propA = 'initial'
    component.propB = 123

    const props: Record<string, any> = {
      propA: 'initial',
      propB: 123,
    }

    const onPropsUpdateSpy = jest
      .fn()
      .mockImplementation((newProps: Record<string, any>) => {
        let changed = false
        Object.keys(newProps).forEach((key) => {
          if (props[key] !== newProps[key]) {
            props[key] = newProps[key]
            changed = true
          }
        })
        return changed
      })

    component.view = new View({
      dependencies: { count: state`count` },
      props: { ...props },
      controller: test.controller,
      displayName: 'InputComponent',
      onUpdate: component.onUpdate,
    })

    component.view.onPropsUpdate = onPropsUpdateSpy

    component.ngOnChanges = function () {
      CerebralComponent.prototype.ngOnChanges.call(this)

      if (this.view) {
        const currentProps: Record<string, any> = {
          propA: this.propA,
          propB: this.propB,
        }
        this.view.onPropsUpdate(currentProps)
      }
    }

    component.propA = 'updated'
    component.ngOnChanges()

    expect(onPropsUpdateSpy).toHaveBeenCalled()
    expect(onPropsUpdateSpy).toHaveBeenCalledWith(
      expect.objectContaining({
        propA: 'updated',
        propB: 123,
      })
    )
  })
})
